/* Corner triangle */
.soharon-badge {
    position: absolute;
    top: 0;
    left: 0;
    width: 84px;
    height: 84px;
    z-index: 20;
    pointer-events: none;
}

.soharon-badge::before {
    content: "";
    position: absolute;
    inset: 0;
    clip-path: polygon(0 0, 100% 0, 0 100%);
}

.soharon-badge--soldout::before {
    background: #000000;
}

.soharon-badge--sale::before {
    background: #E440FF;
}

