.elementor-widget-image .elementor-widget-container {
    position: relative;
    overflow: hidden;
}
.soharon-hover-img {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center center;
    opacity: 0;
    transition: opacity 0.35s ease;
    pointer-events: none;
}
.elementor-widget-image:hover .soharon-hover-img {
    opacity: 1;
}
</style>

<script>
jQuery(document).ready(function ($) {
    function extractProductId($card) {
        var href = $card.find('a.elementor-button-link, a[href*="add-to-cart="]').first().attr('href');
        if (!href) return null;
        var match = href.match(/add-to-cart=(\d+)/);
        return match ? match[1] : null;
    }

    function attachHoverImages() {
        var idMap = {};

        $('.elementor-loop-container').find('.elementor-widget-image').each(function () {
            var $imgWidget = $(this);
            if ($imgWidget.data('hoverAttached')) return;

            // Card wrapper is the swiper-slide, not e-loop-item
            var $card = $imgWidget.closest('.swiper-slide');
            if (!$card.length) return;

            var productId = extractProductId($card);
            if (!productId) return;

            idMap[productId] = idMap[productId] || [];
            idMap[productId].push($imgWidget);
            $imgWidget.data('hoverAttached', true);
        });

        var ids = Object.keys(idMap);
        if (!ids.length) {
            console.log('soharon hover: no product IDs found');
            return;
        }

        console.log('soharon hover: found IDs', ids);

        $.ajax({
            url: soharonHover.ajaxUrl,
            type: 'POST',
            data: {
                action: 'get_hover_images',
                nonce: soharonHover.nonce,
                product_ids: ids
            },
            success: function (response) {
                console.log('soharon hover: ajax response', response);
                if (!response.success) return;
                var images = response.data;

                ids.forEach(function (id) {
                    if (!images[id]) return;
                    idMap[id].forEach(function ($imgWidget) {
                        var $container = $imgWidget.find('.elementor-widget-container').length
                            ? $imgWidget.find('.elementor-widget-container')
                            : $imgWidget;
                        if ($container.find('.soharon-hover-img').length) return;

                        var $hoverImg = $('<img>', {
                            src: images[id],
                            class: 'soharon-hover-img',
                            alt: ''
                        });
                        $container.css('position', 'relative').append($hoverImg);
                    });
                });
            },
            error: function (xhr) {
                console.log('soharon hover: ajax error', xhr.responseText);
            }
        });
    }

    attachHoverImages();

    $(document).on('click', '.shop-cat-nav .cat-link', function () {
        setTimeout(attachHoverImages, 600);
    });
});
</script>"},"elements":[],"widgetType":"html"},{"id":"267603d","elType":"widget","settings":{"image":{"url":"https://soharon.co.uk/dev-101/wp-content/uploads/2026/05/1-1.jpg","id":67,"size":"","alt":"","source":"library"},"image_size":"full","image_border_border":"none","image_border_width":{"unit":"px","top":"1","right":"1","bottom":"1","left":"1","isLinked":true},"image_border_color":"#BCBEC0A6","lqd_parallax_settings_trigger_start":"top bottom","lqd_parallax_settings_trigger_end":"bottom top","width":{"unit":"px","size":388.5,"sizes":[]},"width_tablet":{"unit":"px","size":"","sizes":[]},"width_mobile":{"unit":"px","size":250,"sizes":[]},"object-fit":"cover","__dynamic__":{"image":"[elementor-tag id="70d83f7" name="post-featured-image" settings="%7B%7D"]","link":"[elementor-tag id="ccae800" name="post-url" settings="%7B%7D"]"},"align":"center","height":{"unit":"px","size":388.5,"sizes":[]},"_css_classes":"zoom-img","custom_css":".zoom-img {
